#include <omp.h>
#include <vector>
#include <array>
#include <cstddef>

struct Point {
    double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0, 0, 0, 0};

    #pragma omp parallel
    {
        std::array<size_t, 4> local_bins = {0, 0, 0, 0};

        #pragma omp for nowait
        for (std::size_t i = 0; i < points.size(); ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            if (x > 0 && y > 0) {
                local_bins[0]++;
            } else if (x < 0 && y > 0) {
                local_bins[1]++;
            } else if (x < 0 && y < 0) {
                local_bins[2]++;
            } else if (x > 0 && y < 0) {
                local_bins[3]++;
            }
            // Points on an axis are ignored.
        }

        #pragma omp critical
        {
            for (int q = 0; q < 4; ++q) {
                bins[q] += local_bins[q];
            }
        }
    }
}
